; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: zxn (ZX Spectrum Next - direct hardware (native)), starts in normal mode
; ============================================================

			DEVICE ZXSPECTRUMNEXT		; for SAVENEX at the end
			MMU 0 5, 16			; #0000-#BFFF: pages 16-21 (banks 8, 9, 10)
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
; the ZX Spectrum Next: NTC_ZXN defined (a DEFINE - sjasmplus's IFDEF tests those, not labels)
			DEFINE NTC_ZXN
ZXN_FIRSTBANK	equ 22		; first free 16K bank (page 44), above the program/screen/low banks
ZXN_MAXBANK	equ 90		; scan range: banks 22-111 (a 2MB Next has 112 16K banks, pages 0-223; the MMU has no page past 223 - a higher page number is not RAM)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2		; #0040 (2 bytes): over the glue
ntc_bk_sp:		dw 0			; #0042: this bank's SP while another runs
ntc_bk_out:
			db #08			; #0044: ex af, af - stash A + FLAGS (carry = far-call / interrupt) to the alternate set, before the port flip clobbers A
			ld bc, #243B		; PIVOT via the MMU ports (no Z80N opcode): select MMU slot 0 (#50)
			ld a, #50
			out (c), a
			inc b			; #253B
			ld a, 16		; the hypervisor's slot-0 page; slot 0 flips HERE - next byte is the receiver
			out (c), a
ntc_bk_recv:			; now running in the hypervisor's slot 0 (A + FLAGS already in the alternate set)
			ld (ntc_bk_svd), de	; DE / HL message to slot-0 scratch (slot 0 stays the hypervisor here)
			ld (ntc_bk_svh), hl
			ld hl, ntc_bk_hpg	; the hypervisor's resting pages, slots 1-7
			ld bc, #243B		; NextReg select port (#253B = value)
			ld d, #51		; slot register 1
ntc_bk_rc1:
			ld a, d
			out (c), a		; select the slot register
			inc b			; #253B
			ld a, (hl)
			out (c), a		; = its resting page
			dec b			; #243B
			inc hl
			inc d
			ld a, d
			cp #58			; slots #51..#57 (1..7) done? (clobbers flags - carry safe in AF\')
			jr nz, ntc_bk_rc1
			ld de, (ntc_bk_svd)
			ld hl, (ntc_bk_svh)
			db #08			; ex af, af - A + FLAGS back (IX untouched throughout = also preserved)
ntc_bk_land:
			ld sp, (ntc_bk_sp)	; the hypervisor's own SP
			ret				; to where it handed over (Run's rn_back), A/DE/IX + carry intact
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_bk_svd:		dw 0		; DE / HL message held across the slot 1-7 remap
ntc_bk_svh:		dw 0
ntc_bk_hpg:		db 17, 18, 19, 20, 21, 10, 11	; hypervisor resting pages, slots 1-7 (boot MMU map)
ntc_start2:
ntc_bk_cold:
			di
			ld sp, #C000		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen

			; main.bas 18: Print "Lists on "; System.Platform
			dw kw_printzoscii
			dw glyph_4C, glyph_69, glyph_73, glyph_74, glyph_73, glyph_20, glyph_6F, glyph_6E
			dw glyph_20, glyph_5A, glyph_58, glyph_4E, 1, 0		; "Lists on ZXN\n"

			; main.bas 19: h = List.Create(4)
			dw fn_list_create, lit_4, var_h

			; main.bas 20: seed = 12345
			dw kw_ltov, 12345, var_seed

			; main.bas 21: For i = 1 To 500
			dw kw_ltov, 1, var_i
for1_t:

			; main.bas 22: n = List.Append(h)
			dw fn_list_append, var_h, var_n

			; main.bas 23: If n = 0 Then Print "No room after"; i - 1 : Exit For
			dw kw_l_cpeq, var_n, llit_0
			dw kw_goto_iffalse_n, if2_1
			dw kw_addl, var_i, -1, tmp0
			dw kw_printzoscii
			dw glyph_4E, glyph_6F, glyph_20, glyph_72, glyph_6F, glyph_6F, glyph_6D, glyph_20
			dw glyph_61, glyph_66, glyph_74, glyph_65, glyph_72, 0		; "No room after"
			dw kw_printint, tmp0
			dw kw_printnl
			dw for1_e_go
if2_1:

			; main.bas 24: seed = (seed * 75 + 74) And &H7FFF       ' a small random number generator
			dw kw_mulvl, var_seed, 75, tmp0
			dw kw_addl, tmp0, 74, tmp0
			dw kw_andvl, tmp0, 32767, var_seed

			; main.bas 25: List.SetWord n, ID, i
			dw fn_list_setword, var_n, lit_0, var_i

			; main.bas 26: List.SetWord n, SCORE, seed Mod 10000
			dw kw_modvl, var_seed, 10000, tmp2
			dw fn_list_setword, var_n, lit_2, tmp2

			; main.bas 27: Next
			dw kw_next1l_n, var_i, 500, for1_t
for1_e:

			; main.bas 28: Print List.Count(h); " players"
			dw fn_list_count, var_h, var_list_count_count
			dw kw_printint, var_list_count_count
			dw kw_printzoscii
			dw glyph_20, glyph_70, glyph_6C, glyph_61, glyph_79, glyph_65, glyph_72, glyph_73
			dw 1, 0		; " players\n"

			; main.bas 30: r = List.Sort(h, SCORE)
			dw fn_list_sort, var_h, lit_2, var_r

			; main.bas 31: Print "Top 5:"
			dw kw_printzoscii
			dw glyph_54, glyph_6F, glyph_70, glyph_20, glyph_35, glyph_3A, 1, 0		; "Top 5:\n"

			; main.bas 32: n = List.Last(h)
			dw fn_list_last, var_h, var_n

			; main.bas 33: For i = 1 To 5
			dw kw_ltov, 1, var_i
for3_t:

			; main.bas 34: Print "  player "; List.GetWord(n, ID); ": "; List.GetWord(n, SCORE)
			dw fn_list_getword, var_n, lit_0, var_list_getword_getword
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_70, glyph_6C, glyph_61, glyph_79, glyph_65, glyph_72
			dw glyph_20, 0		; "  player "
			dw kw_printint, var_list_getword_getword
			dw fn_list_getword, var_n, lit_2, var_list_getword_getword
			dw kw_printzoscii
			dw glyph_3A, glyph_20, 0		; ": "
			dw kw_printint, var_list_getword_getword
			dw kw_printnl

			; main.bas 35: n = List.PrevOf(n)
			dw fn_list_prevof, var_n, var_list_prevof_prevof
			dw kw_l_mov, var_list_prevof_prevof, var_n

			; main.bas 36: Next
			dw kw_next1l_n, var_i, 5, for3_t
for3_e:

			; main.bas 39: n = List.First(h)
			dw fn_list_first, var_h, var_n

			; main.bas 40: Do While n <> 0
do4_t:
			dw kw_l_cpne, var_n, llit_0
			dw kw_goto_iffalse_n, do4_e

			; main.bas 41: nxt = List.NextOf(n)
			dw fn_list_nextof, var_n, var_nxt

			; main.bas 42: If List.GetWord(n, SCORE) < 5000 Then r = List.Delete(h, n)
			dw fn_list_getword, var_n, lit_2, var_list_getword_getword
			dw kw_vtov, var_list_getword_getword, tmp0
			dw kw_scpltvl, tmp0, 5000
			dw kw_goto_iffalse_n, if5_1
			dw fn_list_delete, var_h, var_n, var_r
if5_1:

			; main.bas 43: n = nxt
			dw kw_l_mov, var_nxt, var_n

			; main.bas 44: Loop
			dw do4_t_go
do4_e:

			; main.bas 45: Print List.Count(h); " players with 5000 or more"
			dw fn_list_count, var_h, var_list_count_count
			dw kw_printint, var_list_count_count
			dw kw_printzoscii
			dw glyph_20, glyph_70, glyph_6C, glyph_61, glyph_79, glyph_65, glyph_72, glyph_73
			dw glyph_20, glyph_77, glyph_69, glyph_74, glyph_68, glyph_20, glyph_35, glyph_30
			dw glyph_30, glyph_30, glyph_20, glyph_6F, glyph_72, glyph_20, glyph_6D, glyph_6F
			dw glyph_72, glyph_65, 1, 0		; " players with 5000 or more\n"

			; main.bas 46: n = List.Search(h, ID, 250)
			dw fn_list_search, var_h, lit_0, lit_250, var_n

			; main.bas 47: If n <> 0 Then Print "Player 250 scored "; List.GetWord(n, SCORE) Else Print "Player 250 is gone"
			dw kw_l_cpne, var_n, llit_0
			dw kw_goto_iffalse_n, if6_1
			dw fn_list_getword, var_n, lit_2, var_list_getword_getword
			dw kw_printzoscii
			dw glyph_50, glyph_6C, glyph_61, glyph_79, glyph_65, glyph_72, glyph_20, glyph_32
			dw glyph_35, glyph_30, glyph_20, glyph_73, glyph_63, glyph_6F, glyph_72, glyph_65
			dw glyph_64, glyph_20, 0		; "Player 250 scored "
			dw kw_printint, var_list_getword_getword
			dw kw_printnl
			dw if6_e_go
if6_1:
			dw kw_printzoscii
			dw glyph_50, glyph_6C, glyph_61, glyph_79, glyph_65, glyph_72, glyph_20, glyph_32
			dw glyph_35, glyph_30, glyph_20, glyph_69, glyph_73, glyph_20, glyph_67, glyph_6F
			dw glyph_6E, glyph_65, 1, 0		; "Player 250 is gone\n"
if6_e:

			; main.bas 48: r = List.Destroy(h)
			dw fn_list_destroy, var_h, var_r

			; main.bas 50: End
			dw kw_printnl0
			dw kw_printzoscii
			dw glyph_50, glyph_72, glyph_65, glyph_73, glyph_73, glyph_20, glyph_61, glyph_20
			dw glyph_6B, glyph_65, glyph_79, 0		; "Press a key"
			dw kw_waitkey
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

for1_e_go:			ld sp, for1_e
			jp ntc_xn
do4_t_go:			ld sp, do4_t
			jp ntc_xn
if6_e_go:			ld sp, if6_e
			jp ntc_xn

